const scraped = $input.first().json;
const webhook = $('Webhook').first().json.body;

const title = scraped.title || scraped.item_name || '';

// Strip lot number prefix from title for clean item name
const cleanTitle = title
  .replace(/^lot\s*#?\s*:?\s*\d+[a-z]*\s*-?\s*/gi, '')   // "Lot # : 49901d -" fully stripped
  .replace(/^#\s*:?\s*\d+[a-z]*\s*-?\s*/gi, '')           // "# : 49901d -" variant
  .replace(/^[a-z]\s*-\s*/i, '')                          // safety net: any leftover "d -" prefix
  .trim();

// Derive a basic description from the clean title
const description = cleanTitle;

// Derive category from keywords in title
const titleLower = cleanTitle.toLowerCase();
let category = 'Collectibles';
if (titleLower.match(/dollar|coin|cent|dime|quarter|silver|gold|morgan|mercury/)) category = 'Coins & Currency';
else if (titleLower.match(/painting|print|lithograph|watercolor|art|drawing/)) category = 'Art';
else if (titleLower.match(/watch|rolex|omega|breitling/)) category = 'Watches';
else if (titleLower.match(/ring|necklace|bracelet|earring|jewelry|diamond/)) category = 'Jewelry';
else if (titleLower.match(/furniture|chair|table|cabinet|dresser/)) category = 'Furniture';
else if (titleLower.match(/toy|doll|lego|figurine|action figure/)) category = 'Toys';
else if (titleLower.match(/book|magazine|poster|photograph|postcard/)) category = 'Paper & Ephemera';
else if (titleLower.match(/gun|rifle|pistol|firearm|ammunition/)) category = 'Firearms';
else if (titleLower.match(/tool|wrench|saw|drill/)) category = 'Tools';

return [{
  json: {
    itemId: webhook.itemId,
    adminId: webhook.adminId,
    adminEmail: webhook.adminEmail,
    url_main: webhook.url_main,
    title: cleanTitle,
    lot_number: scraped.lot_number || '',
    description: description,
    category: category,
    estimate: '',
    auction_name: scraped.auction_name || '',
    images: Array.isArray(scraped.images) ? scraped.images : [],
    main_image_url: scraped.main_image_url || (Array.isArray(scraped.images) ? scraped.images[0] : '') || ''
  }
}];

const merged = $('Merge forgery data').first().json;
const categoryResults = $input.first().json.results || [];
const title = merged.title || '';
const description = merged.description || '';

// Strip lot numbers, prefixes, special characters aggressively
const cleaned = title
  .replace(/lot\s*#?\s*:?\s*\d+\w*\s*-?\s*/gi, '')  // strip "Lot # : 8501 -" style prefixes
  .replace(/#\s*:?\s*\d+\w*\s*-?\s*/gi, '')           // strip "# : 8501 -" style
  .replace(/^\d+\w*\s*-?\s*/g, '')                     // strip leading numbers like "49901d"
  .replace(/^[\s\-_#:,\.]*[a-zA-Z]?\s*[\-_#:,\.]+\s*/i, '')                     // strip leading junk chars including lone 'd'
  .replace(/\b(circa|approx|vintage|antique|estate|lot)\b/gi, '')
  .replace(/\s+/g, ' ')
  .trim();

const searchQuery = cleaned || description.substring(0, 80);

const notExactKeywords = ['original', 'signed', 'oil painting', 'watercolor', 'hand made', 'one of a kind', 'unique'];
const isExactMatchable = !notExactKeywords.some(k => (title + description).toLowerCase().includes(k));

const highFakeRiskKeywords = ['rolex', 'gucci', 'louis vuitton', 'chanel', 'cartier', 'prada', 'hermes', 'breitling', 'omega watch'];
const fakeRisk = highFakeRiskKeywords.some(k => (title + description).toLowerCase().includes(k)) ? 'high' : 'none';

return [{
  json: {
    ...merged,
    categoryResults,
    searchQuery,
    isExactMatchable,
    fakeRisk,
    categoryMatchCount: categoryResults.length
  }
}];

const prev = $('Build exact match query').first().json;
const serperData = $input.first().json;

const items = serperData.organic || [];
const topUrls = items.slice(0, 5).map(i => ({
  url: i.link,
  title: i.title,
  snippet: i.snippet
}));

const shopping = (serperData.shopping || []).slice(0, 3).map(i => ({
  url: i.link || '',
  title: i.title,
  snippet: `Price: ${i.price || 'unknown'}`
}));

// peopleAlsoAsk often contains direct price data — very valuable
const paa = (serperData.peopleAlsoAsk || []).slice(0, 3).map(i => ({
  url: i.link || '',
  title: i.question,
  snippet: i.snippet
}));

const allResults = [...topUrls, ...shopping, ...paa];

return [{
  json: {
    ...prev,
    serperResults: allResults,
    googleResultsText: allResults.map(r => `${r.title}: ${r.snippet} (${r.url})`).join('\n')
  }
}];

