const prev = $('Store item_db IDs').first().json;
const clientId = 'REDACTED';
const clientSecret = 'REDACTED';
const credentials = Buffer.from(`${clientId}:${clientSecret}`).toString('base64');

return [{
  json: {
    ...prev,
    ebayAuthHeader: `Basic ${credentials}`
  }
}];

const soldData = $('Search eBay sold listings').first().json;
const activeData = $('Search eBay active listings').first().json;
const prev = $('Merge final confidence').first().json;

// Process sold listings
const soldItems = soldData.itemSummaries || [];
const rawSoldPrices = soldItems
  .map(i => parseFloat(i.price?.value || 0))
  .filter(p => p > 0)
  .sort((a, b) => a - b);

// Process active listings
const activeItems = activeData.itemSummaries || [];
const activePrices = activeItems
  .map(i => parseFloat(i.price?.value || 0))
  .filter(p => p > 0)
  .sort((a, b) => a - b);

// Strip outliers from sold prices using cluster method
let trimmedSoldPrices = rawSoldPrices;
let removedPrices = [];
let removalReason = 'No outliers removed';

if (rawSoldPrices.length > 0) {
  const median = rawSoldPrices[Math.floor(rawSoldPrices.length / 2)];
  const clusterThreshold = median * 0.25;
  trimmedSoldPrices = rawSoldPrices.filter(p => p >= clusterThreshold);
  removedPrices = rawSoldPrices.filter(p => p < clusterThreshold);
  if (removedPrices.length > 0) {
    removalReason = `Removed ${removedPrices.length} prices below cluster threshold of $${clusterThreshold.toFixed(2)}`;
  }
}

const trimmedMin = trimmedSoldPrices.length > 0 ? Math.min(...trimmedSoldPrices) : 0;
const trimmedMax = trimmedSoldPrices.length > 0 ? Math.max(...trimmedSoldPrices) : 0;
const trimmedMedian = trimmedSoldPrices.length > 0
  ? trimmedSoldPrices[Math.floor(trimmedSoldPrices.length / 2)]
  : 0;

const activeMin = activePrices.length > 0 ? Math.min(...activePrices) : 0;
const activeMax = activePrices.length > 0 ? Math.max(...activePrices) : 0;

// Reference URLs from sold listings within trimmed range
const referenceUrls = soldItems
  .filter(i => {
    const p = parseFloat(i.price?.value || 0);
    return p >= trimmedMin && p <= trimmedMax;
  })
  .slice(0, 6)
  .map(i => ({
    url: i.itemWebUrl || '',
    platform: 'ebay',
    title: i.title || '',
    soldPrice: parseFloat(i.price?.value || 0),
    condition: i.condition || ''
  }));

// Active listing URLs for context
const activeReferenceUrls = activeItems
  .slice(0, 3)
  .map(i => ({
    url: i.itemWebUrl || '',
    platform: 'ebay',
    title: i.title || '',
    listedPrice: parseFloat(i.price?.value || 0),
    condition: i.condition || ''
  }));

return [{
  json: {
    ...prev,
    rawPrices: rawSoldPrices,
    trimmedPrices: trimmedSoldPrices,
    trimmedMin,
    trimmedMax,
    trimmedMedian,
    removedPrices,
    removalReason,
    activePrices,
    activeMin,
    activeMax,
    priceRangeLabel: trimmedSoldPrices.length > 0
      ? `$${trimmedMin.toFixed(0)} – $${trimmedMax.toFixed(0)}`
      : 'No sold data',
    activeRangeLabel: activePrices.length > 0
      ? `$${activeMin.toFixed(0)} – $${activeMax.toFixed(0)}`
      : 'No active listings',
    referenceUrls,
    activeReferenceUrls
  }
}];

const imageAnalysis = $input.first().json?.content?.[0]?.text || 'No image analysis available';
const prev = $('Compute price range').first().json;

return [{ json: { ...prev, imageAnalysis } }];

