const textRaw = $input.first().json;
const imageData = $('Merge1').first().json;
const original = $('Store item_db IDs').first().json;

let textMatch = { textMatchScore: 0.3, textMatchNotes: 'parse error' };
try {
  const raw = textRaw?.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  textMatch = JSON.parse(cleaned);
} catch(e) {
  console.error('Text match parse error:', e.message);
}

let finalConfidence;
let confidenceLabel;

if (imageData.imageMatchAvailable) {
  const imageScore = imageData.mergedConfidence;
  const textScore = textMatch.textMatchScore;

  if (imageScore >= 0.85 && textScore >= 0.85) {
    finalConfidence = 0.99;
    confidenceLabel = 'bingo — image and text both confirm exact match';
  } else {
    finalConfidence = (imageScore * 0.6) + (textScore * 0.4);
    confidenceLabel = `merged — image ${(imageScore*100).toFixed(0)}%, text ${(textScore*100).toFixed(0)}%`;
  }
} else {
  finalConfidence = Math.min(textMatch.textMatchScore * 0.5, 0.4);
  confidenceLabel = 'text only — no image comparables survived rejection gate';
}

return [{
  json: {
    ...original,
    confidenceScore: finalConfidence, // overrides the original text-only confidence
    confidenceLabel,
    imageMatchAvailable: imageData.imageMatchAvailable,
    survivingListingsCount: imageData.survivingCount || 0,
    textMatchScore: textMatch.textMatchScore,
    textMatchNotes: textMatch.textMatchNotes,
    imageConfidenceNotes: imageData.confidenceNotes || null
  }
}];

const item = $('Merge scrape + webhook data').first().json;
const settings = $input.first().json || {};

const text = ((item.title || '') + ' ' + (item.description || '')).toLowerCase();

const buckets = {
  furniture: {
    excluded: settings.exclude_furniture === true,
    label: 'furniture',
    keywords: ['dresser', 'armoire', 'hutch', 'couch', 'sofa', 'loveseat', 'recliner',
      'bed frame', 'headboard', 'nightstand', 'wardrobe', 'credenza', 'sideboard',
      'dining table', 'dining set', 'coffee table', 'end table', 'bookcase', 'bookshelf',
      'china cabinet', 'curio cabinet', 'pool table', 'piano', 'desk', 'ottoman', 'futon',
      'sectional', 'entertainment center', 'chest of drawers', 'vanity']
  },
  appliances: {
    excluded: settings.exclude_appliances === true,
    label: 'appliances',
    keywords: ['refrigerator', 'fridge', 'freezer', 'washer', 'dryer', 'washing machine',
      'dishwasher', 'stove', 'oven', 'range', 'microwave', 'air conditioner', 'water heater',
      'furnace', 'deep freeze', 'chest freezer']
  },
  coins: {
    excluded: settings.exclude_coins === true,
    label: 'coins & collectibles',
    keywords: ['coin', 'morgan dollar', 'peace dollar', 'silver dollar', 'silver eagle',
      'gold eagle', 'nickel', 'dime', 'quarter', 'half dollar', 'penny', 'cent',
      'mint state', 'pcgs', 'ngc', 'proof set', 'mint set', 'bullion', 'numismatic']
  },
  firearms: {
    excluded: settings.exclude_firearms === true,
    label: 'firearms',
    keywords: ['rifle', 'pistol', 'shotgun', 'handgun', 'revolver', 'firearm', 'ammunition',
      'ammo', 'gun ', ' gun', 'carbine', 'muzzleloader']
  },
  vehicles: {
    excluded: settings.exclude_vehicles === true,
    label: 'vehicles',
    keywords: ['sedan', 'pickup truck', 'suv', 'motorcycle', 'atv', 'utv', 'boat', 'trailer',
      'camper', 'rv ', 'golf cart', 'tractor', 'mileage', 'vin ', 'odometer', 'title in hand']
  },
  realEstate: {
    excluded: true, // always, no toggle
    label: 'real estate',
    keywords: ['real estate', 'acres', 'acreage', 'parcel', 'land lot', 'property located',
      'sq ft home', 'bedroom home', 'commercial building', 'vacant land', 'deed']
  }
};

let excluded = false;
let exclusionReason = '';

for (const key of Object.keys(buckets)) {
  const b = buckets[key];
  if (!b.excluded) continue;
  const hit = b.keywords.find(kw => text.includes(kw));
  if (hit) {
    excluded = true;
    exclusionReason = b.label + ' (matched: "' + hit.trim() + '")';
    break;
  }
}

return [{
  json: {
    ...item,
    excluded,
    exclusionReason
  }
}];
